import java.util.*;

class Solution {
    public int solvePatternExample(int[] nums) {
        Map<Integer, Integer> state = new HashMap<>();
        int answer = 0;
        int running = 0;
        state.put(0, 1);

        for (int value : nums) {
            running += value;
            answer += state.getOrDefault(running, 0);
            state.put(running, state.getOrDefault(running, 0) + 1);
        }

        return answer;
    }
}

